<script setup lang="ts">
const localeTag = useLocaleTag()
import { ArrowUpRight } from 'lucide-vue-next'
const { t, locale }=useI18n(),localePath=useLocalePath(),page=ref(1)
const {data,status}=await useFetch('/api/blog',{query:{page}})
const date=(value:string)=>new Intl.DateTimeFormat(localeTag.value,{dateStyle:'medium',timeZone:'UTC'}).format(new Date(value))
</script>
<template><div><p v-if="status==='pending'&&!data" role="status">{{ t('common.loading') }}</p><div v-if="data?.items.length" class="blog-grid"><article v-for="post in data.items" :key="post.id" class="blog-card"><NuxtLink :to="localePath(`/blog/${post.slug}`)" tabindex="-1" aria-hidden="true"><NuxtImg v-if="post.image" :src="post.image" alt="" width="640" height="390" format="webp" loading="lazy" class="blog-image" /><img v-else src="/images/blog-fallback.svg" alt="" width="640" height="390" loading="lazy" class="blog-image"></NuxtLink><time :datetime="post.date">{{ date(post.date) }}</time><h3><NuxtLink :to="localePath(`/blog/${post.slug}`)">{{ post.title }}</NuxtLink></h3><p>{{ post.excerpt }}</p><a class="text-link" :href="post.url">{{ t('common.original') }}<ArrowUpRight :size="16" /></a></article></div><div v-else class="empty-state"><p>{{ t('blog.empty') }}</p><a class="button" href="https://medium.com/@obahamonde">{{ t('blog.visit') }} ↗</a></div><p v-if="data?.stale&&data.items.length" class="fineprint">{{ t('blog.stale') }}</p><nav v-if="data&&data.pages>1" class="pagination" :aria-label="t('nav.blog')"><button class="button" :disabled="page<=1||status==='pending'" @click="page--">{{ t('common.previous') }}</button><span>{{ page }} / {{ data.pages }}</span><button class="button" :disabled="page>=data.pages||status==='pending'" @click="page++">{{ t('common.next') }}</button></nav></div></template>
